function output = heartlib(M)
% output = heartlib(M)
%
%    ElementSets, BoundaryMatrices, UnsignedBoundaryMatrices, NonZeros, IndicatorVector from MeshConnectivity
%    
%    M : CellMesh
%    
%    V, E, F, C = ElementSets( M )
%    `∂⁰`, `∂¹`, `∂²` = BoundaryMatrices(M) 
%    `B⁰`, `B¹`, `B²` = UnsignedBoundaryMatrices(M)
%    `B⁰ᵀ` = `B⁰`ᵀ
%    `B¹ᵀ` = `B¹`ᵀ
%    `B²ᵀ` = `B²`ᵀ
%    
%    Vertices(S) = S₁ where S: CellularSet
%    Edges(S)    = S₂ where S: CellularSet 
%    Faces(S)    = S₃ where S: CellularSet
%    Cells(S)    = S₄ where S: CellularSet
%     
%    Vertices(f) = vertexset(NonZeros(`B⁰` (`B¹` IndicatorVector({f})))) where f ∈ F
%    Vertices(G) = vertexset(NonZeros(`B⁰` (`B¹` IndicatorVector(G)))) where G ⊂ F
%    Vertices(t) = vertexset(NonZeros(`B⁰` (`B¹` (`B²` IndicatorVector({t}))))) where t ∈ C
%    Vertices(J) = vertexset(NonZeros(`B⁰` (`B¹` (`B²` IndicatorVector(J))))) where J ⊂ C
%    Vertices(e) = vertexset(NonZeros(`B⁰` IndicatorVector({e}))) where e ∈ E
%    Vertices(H) = vertexset(NonZeros(`B⁰` IndicatorVector(H))) where H ⊂ E
%     
%    Edges(v) = edgeset(NonZeros(`B⁰ᵀ` IndicatorVector({v}))) where v ∈ V
%    Edges(f) = edgeset(NonZeros(`B¹` IndicatorVector({f}))) where f ∈ F
%    Edges(t) = edgeset(NonZeros(`B¹` (`B²` IndicatorVector({t})))) where t ∈ C
%    
%    Faces(v) = faceset(NonZeros(`B¹ᵀ` (`B⁰ᵀ` IndicatorVector({v})))) where v ∈ V
%    Faces(e) = faceset(NonZeros(`B¹ᵀ` IndicatorVector({e}))) where e ∈ E
%    Faces(t) = faceset(NonZeros(`B²` IndicatorVector({t}))) where t ∈ C
    dimv_0 = M.n_vertices();
    dime_0 = M.n_edges();
    dimf_0 = M.n_faces();
    [V, E, F, C] = M.ElementSets();
    [dee0, dee1, dee2] = M.BoundaryMatrices();
    [B0, B1, B2] = M.UnsignedBoundaryMatrices();
    % `B⁰ᵀ` = `B⁰`ᵀ

    B0T = B0';
    % `B¹ᵀ` = `B¹`ᵀ

    B1T = B1';
    % `B²ᵀ` = `B²`ᵀ

    B2T = B2';
    function [ret] = Vertices(S)
        ret = S(1);
    end

    function [ret_1] = Edges(S)
        ret_1 = S(2);
    end

    function [ret_2] = Faces(S)
        ret_2 = S(3);
    end

    function [ret_3] = Cells(S)
        ret_3 = S(4);
    end

    function [ret_4] = Vertices_0(f)
        assert(numel(f) == 1);
        assert( ismember(f, F) );

        ret_4 = NonZeros(B0 * (B1 * indicator([f], M.n_faces())));
    end

    function [ret_5] = Vertices_1(G)
        ret_5 = NonZeros(B0 * (B1 * indicator(G, M.n_faces())));
    end

    function [ret_6] = Vertices_2(t)
        assert(numel(t) == 1);
        assert( ismember(t, C) );

        ret_6 = NonZeros(B0 * (B1 * (B2 * indicator([t], M.n_tets()))));
    end

    function [ret_7] = Vertices_3(J)
        ret_7 = NonZeros(B0 * (B1 * (B2 * indicator(J, M.n_tets()))));
    end

    function [ret_8] = Vertices_4(e)
        assert(numel(e) == 1);
        assert( ismember(e, E) );

        ret_8 = NonZeros(B0 * indicator([e], M.n_edges()));
    end

    function [ret_9] = Vertices_5(H)
        ret_9 = NonZeros(B0 * indicator(H, M.n_edges()));
    end

    function [ret_10] = Edges_0(v)
        assert(numel(v) == 1);
        assert( ismember(v, V) );

        ret_10 = NonZeros(B0T * indicator([v], M.n_vertices()));
    end

    function [ret_11] = Edges_1(f)
        assert(numel(f) == 1);
        assert( ismember(f, F) );

        ret_11 = NonZeros(B1 * indicator([f], M.n_faces()));
    end

    function [ret_12] = Edges_2(t)
        assert(numel(t) == 1);
        assert( ismember(t, C) );

        ret_12 = NonZeros(B1 * (B2 * indicator([t], M.n_tets())));
    end

    function [ret_13] = Faces_0(v)
        assert(numel(v) == 1);
        assert( ismember(v, V) );

        ret_13 = NonZeros(B1T * (B0T * indicator([v], M.n_vertices())));
    end

    function [ret_14] = Faces_1(e)
        assert(numel(e) == 1);
        assert( ismember(e, E) );

        ret_14 = NonZeros(B1T * indicator([e], M.n_edges()));
    end

    function [ret_15] = Faces_2(t)
        assert(numel(t) == 1);
        assert( ismember(t, C) );

        ret_15 = NonZeros(B2 * indicator([t], M.n_tets()));
    end

    output.V = V;
    output.E = E;
    output.F = F;
    output.C = C;
    output.dee0 = dee0;
    output.dee1 = dee1;
    output.dee2 = dee2;
    output.B0 = B0;
    output.B1 = B1;
    output.B2 = B2;
    output.B0T = B0T;
    output.B1T = B1T;
    output.B2T = B2T;
    output.Vertices = @Vertices;
    output.Edges = @Edges;
    output.Faces = @Faces;
    output.Cells = @Cells;
    output.Vertices_0 = @Vertices_0;
    output.Vertices_1 = @Vertices_1;
    output.Vertices_2 = @Vertices_2;
    output.Vertices_3 = @Vertices_3;
    output.Vertices_4 = @Vertices_4;
    output.Vertices_5 = @Vertices_5;
    output.Edges_0 = @Edges_0;
    output.Edges_1 = @Edges_1;
    output.Edges_2 = @Edges_2;
    output.Faces_0 = @Faces_0;
    output.Faces_1 = @Faces_1;
    output.Faces_2 = @Faces_2;
    output.M = M;
end

